package leetcode.medium;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import java.util.Arrays;

public class OnlineStockSpanTest {

    @Test
    public void next_0Is1_test() {
        OnlineStockSpan onlineStockSpan = new OnlineStockSpan();
        int result = onlineStockSpan.next(0);
        assertEquals(1, result);
    }

    @Test
    public void next_100Is1_test() {
        OnlineStockSpan onlineStockSpan = new OnlineStockSpan();
        int result = onlineStockSpan.next(100);
        assertEquals(1, result);
    }

    @Test
    public void next_negativeNumberIs0_test() {
        OnlineStockSpan onlineStockSpan = new OnlineStockSpan();
        int result = onlineStockSpan.next(-5);
        assertEquals(0, result);
    }

    @Test
    public void calculateSpans_EmptyArray_test() {
        OnlineStockSpan onlineStockSpan = new OnlineStockSpan();
        int[] result = onlineStockSpan.calculateSpans(new int[0]);
        assert result == null;
    }

    @Test
    public void calculateSpans_SingleElementArray_test() {
        OnlineStockSpan onlineStockSpan = new OnlineStockSpan();
        int[] result = onlineStockSpan.calculateSpans(new int[]{10});
        assertEquals(1, Arrays.stream(result).max().getAsInt());
    }

    @Test
    public void calculateSpans_MultipleElementsArray_test() {
        OnlineStockSpan onlineStockSpan = new OnlineStockSpan();
        int[] result = onlineStockSpan.calculateSpans(new int[]{15, 3, -10});
        assertEquals(2, Arrays.stream(result).max().getAsInt());
    }
}

